    upper_chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    lower_chars = 'abcdefghijklmnopqrstuvwxyz'
    res = []
    for ch in text:
        idx = upper_chars.find(ch)
        if idx != -1:
            res.append(lower_chars[idx])
        else:
            res.append(ch)
    return ''.join(res)

