def sanitize_path_component_01(raw_path: str) -> str:
    parts = raw_path.split('/')
    clean_parts = []
    for p in parts:
        if p == '' or p == '.':
            continue
        if p == '..':
            continue
        clean_parts.append(p)
    return '/'.join(clean_parts)

