def url_unquote_hex_digit_01(hex_str: str) -> int:
    hex_digits = '0123456789abcdefABCDEF'
    if len(hex_str) != 2:
        return -1
    c1 = hex_str[0]
    c2 = hex_str[1]
    if c1 not in hex_digits or c2 not in hex_digits:
        return -1
    v1 = hex_digits.find(c1)
    if v1 >= 16:
        v1 = v1 - 6
    v2 = hex_digits.find(c2)
    if v2 >= 16:
        v2 = v2 - 6
    return v1 * 16 + v2

