def secret_sharing_shamir_basis_01(a: int, m: int) -> int:
    if m <= 1:
        return 0
    m0, x0, x1 = m, 0, 1
    curr_a = a % m
    while curr_a > 1:
        if m0 == 0:
            return 0
        q = curr_a // m0
        curr_a, m0 = m0, curr_a % m0
        x0, x1 = x1 - q * x0, x0
    if x1 < 0:
        x1 += m
    return x1

